def bundle(ext):
 p=A/f'collapse-event-system.{ext}'; name=f'collapse-event-system-{hashlib.sha256(p.read_bytes()).hexdigest()[:12]}.{ext}';(A/name).write_bytes(p.read_bytes());return '/assets/'+name
